package mz.gov.mogovolas.expedientes;
import mz.gov.mogovolas.expedientes.entity.*; import mz.gov.mogovolas.expedientes.repository.*; import mz.gov.mogovolas.expedientes.service.*; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class ExpedienteServiceTest { @Test void deveCriarComNumeroESector(){var er=Mockito.mock(ExpedienteRepository.class);var ur=Mockito.mock(UtilizadorRepository.class);var sr=Mockito.mock(SectorRepository.class);var tr=Mockito.mock(TramitacaoRepository.class);var dr=Mockito.mock(DespachoRepository.class);var u=new Utilizador();var s=new Sector("Secretaria","x");u.setSector(s);u.setUsername("ana");Mockito.when(ur.findByUsername("ana")).thenReturn(Optional.of(u));Mockito.when(er.count()).thenReturn(0L);Mockito.when(er.save(Mockito.any())).thenAnswer(x->x.getArgument(0));var svc=new ExpedienteService(er,ur,sr,tr,dr);var e=new Expediente();e.setAssunto("Teste");var out=svc.criar(e,"ana");assertEquals("EXP-"+java.time.Year.now().getValue()+"-00001",out.getNumero());assertSame(s,out.getSectorActual());assertEquals(Expediente.EstadoExpediente.REGISTADO,out.getEstado());}}
